package com.bank.recon;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.groupingBy;

public class StyleDemo {
    private static final Logger log = Logger.getLogger(StyleDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        var txns = new ArrayList<Transaction>();     // GOOD var: type obvious
        txns.add(new Transaction("SAV2001", new BigDecimal("50000.00")));
        txns.add(new Transaction("SAV2001", new BigDecimal("25000.00")));
        txns.add(new Transaction("CUR3001", new BigDecimal("10000.00")));

        // GOOD var: stream pipeline intermediate; exact collector type is noise.
        var byAccount = txns.stream().collect(groupingBy(Transaction::getAccountId));

        // AVOID var here — explicit type documents the return at the call site.
        ReconciliationService service = new ReconciliationService();
        FeeResult fee = service.calculateMonthlyFee("SAV2001", byAccount);
        log.info(() -> "Fee for SAV2001: Rs." + fee.getAmount() + " (" + fee.getReason() + ")");

        // AVOID var for a width-sensitive counter — explicit long is intentional.
        long paiseCount = 0L;
        for (var txn : txns) {                        // GOOD var: element type obvious
            paiseCount += txn.getAmount().movePointRight(2).longValueExact();
        }
        final long finalCount = paiseCount;
        log.info(() -> "Total paise across all transactions: " + finalCount);

        // DIAMOND TRAP corrected: put the type argument on the RIGHT with var.
        var accountIds = new ArrayList<String>();     // ArrayList<String>, not <Object>
        byAccount.keySet().forEach(accountIds::add);
        log.info(() -> "Reconciled accounts: " + accountIds);
    }
}

// ─── Would be in model/Transaction.java ───
class Transaction {
    private final String accountId;
    private final BigDecimal amount;
        Transaction(String accountId, BigDecimal amount) { this.accountId = accountId;
        this.amount = amount; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in model/FeeResult.java ───
class FeeResult {
    private final BigDecimal amount;
    private final String reason;
        FeeResult(BigDecimal amount, String reason) { this.amount = amount;
        this.reason = reason; }
    BigDecimal getAmount() { return amount; }
    String getReason() { return reason; }
}

// ─── Would be in service/ReconciliationService.java ───
class ReconciliationService {
    // Return type is EXPLICIT here — callers must know what they get.
    FeeResult calculateMonthlyFee(String accountId, Map<String, List<Transaction>> byAccount) {
        var count = byAccount.getOrDefault(accountId, List.of()).size();  // local var fine
        BigDecimal fee = count > 1 ? new BigDecimal("100.00") : new BigDecimal("50.00");
        return new FeeResult(fee, count + " transactions this month");
    }
}
